1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = { premium: number } | { payout: number; remainingCap: number };
41	
42	const sumBy = <T>(values: T[], amountOf: (value: T) => number): number =>
43	  values.reduce((total, value) => total + amountOf(value), 0);
44	
45	const PROCESSING_FEE = 5;
46	
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	
49	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
50	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
51	
52	/**
53	 * The MHPCO's price list: the closed set of insurable item types, each with its
54	 * base premium and insurance value in gold. The two numbers live in one table
55	 * so a new item type cannot be given a premium but no insurance value.
56	 */
57	const PRICE_LIST = {
58	  sword: { basePremium: 100, insuranceValue: 1000 },
59	  amulet: { basePremium: 60, insuranceValue: 600 },
60	  staff: { basePremium: 80, insuranceValue: 800 },
61	  potion: { basePremium: 40, insuranceValue: 400 },
62	  rune: { basePremium: 25, insuranceValue: 250 },
63	  moonstone: { basePremium: 25, insuranceValue: 250 },
64	} as const satisfies Record<string, { basePremium: number; insuranceValue: number }>;
65	
66	export type ItemType = keyof typeof PRICE_LIST;
67	
68	const isInsurableType = (type: string): type is ItemType => type in PRICE_LIST;
69	
70	/** The MHPCO does not insure what is not in its price list. */
71	const priceOf = (item: Item) => {
72	  if (!isInsurableType(item.type)) throw new Error(`Unknown item type: ${item.type}`);
73	  return PRICE_LIST[item.type];
74	};
75	
76	const basePremiumOf = (item: Item): number => priceOf(item).basePremium;
77	
78	const BLOCK_SIZE = 3;
79	const BLOCK_BASE_PREMIUM = 60;
80	
81	/** Groups items by type; "alike" means same type, not same family. */
82	const groupByType = (items: Item[]): Item[][] => {
83	  const types = [...new Set(items.map((item) => item.type))];
84	  return types.map((type) => items.filter((item) => item.type === type));
85	};
86	
87	const COMPONENT_TYPES = new Set<string>(["rune", "moonstone"]);
88	
89	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
90	
91	/** Three alike components form a block, priced at a special base premium. */
92	const basePremiumOfGroup = (group: Item[]): number =>
93	  group.length === BLOCK_SIZE && group.every(isComponent)
94	    ? BLOCK_BASE_PREMIUM
95	    : sumBy(group, basePremiumOf);
96	
97	const totalBasePremium = (items: Item[]): number =>
98	  sumBy(groupByType(items), basePremiumOfGroup);
99	
100	const CURSE_SURCHARGE_RATE = 0.5;
101	
102	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
103	const HIGH_ENCHANTMENT_THRESHOLD = 5;
104	
105	const isCursed = (item: Item): boolean => item.cursed === true;
106	
107	const isHighlyEnchanted = (item: Item): boolean =>
108	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
109	
110	const itemSurchargeRate = (item: Item): number =>
111	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
112	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
113	
114	/**
115	 * Item-specific surcharges apply to the affected item's own base premium,
116	 * unlike policy-wide modifiers which apply to the policy's total base premium.
117	 *
118	 * NOTE: this uses each item's ungrouped base premium, so a cursed component
119	 * inside a 3-alike block is surcharged against its own 25 G rather than its
120	 * share of the block's 60 G. No test covers that combination yet; the choice
121	 * is unverified, not deliberate.
122	 */
123	const totalItemSurcharges = (items: Item[]): number =>
124	  sumBy(items, (item) => basePremiumOf(item) * itemSurchargeRate(item));
125	
126	const LOYALTY_DISCOUNT_RATE = 0.2;
127	const LOYALTY_THRESHOLD_YEARS = 2;
128	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
129	
130	const isLoyal = (customer: Customer): boolean =>
131	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
132	
133	/**
134	 * Policy-wide modifiers apply to the policy's base premium, not to the item
135	 * surcharges. Returns a signed rate: the first-insurance surcharge less the
136	 * loyalty discount, so a loyal customer's rate can be negative.
137	 */
138	const policyModifierRate = (customer: Customer, isFollowUpContract: boolean): number =>
139	  FIRST_INSURANCE_SURCHARGE_RATE -
140	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
141	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
142	
143	const quotePremium = (
144	  items: Item[],
145	  customer: Customer,
146	  isFollowUpContract: boolean,
147	): number => {
148	  const basePremium = totalBasePremium(items);
149	  const premiumBeforeFee =
150	    basePremium +
151	    totalItemSurcharges(items) +
152	    basePremium * policyModifierRate(customer, isFollowUpContract);
153	  return roundPremium(premiumBeforeFee + PROCESSING_FEE);
154	};
155	
156	const insuranceValueOf = (item: Item): number => priceOf(item).insuranceValue;
157	
158	const DEDUCTIBLE = 100;
159	const CAP_MULTIPLIER = 2;
160	
161	/** Rounds down in the MHPCO's favor. */
162	const roundPayout = (amount: number): number => Math.floor(Number(amount.toFixed(6)));
163	
164	interface Policy {
165	  items: Item[];
166	  remainingCap: number;
167	}
168	
169	const openPolicy = (items: Item[]): Policy => ({
170	  items,
171	  remainingCap: sumBy(items, insuranceValueOf) * CAP_MULTIPLIER,
172	});
173	
174	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
175	const HALVED_REIMBURSEMENT_RATE = 0.5;
176	const FULL_REIMBURSEMENT_RATE = 1;
177	
178	/** Damage to a heavily enchanted item is only half reimbursed. */
179	const reimbursementRate = (item: Item): number =>
180	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD
181	    ? HALVED_REIMBURSEMENT_RATE
182	    : FULL_REIMBURSEMENT_RATE;
183	
184	/** A damage paired with the specific insured item it was matched against. */
185	interface MatchedDamage {
186	  damage: Damage;
187	  item: Item;
188	}
189	
190	/**
191	 * A damage names only an item type, so the insured item it refers to — and
192	 * hence its enchantment and material — has to be looked up on the policy.
193	 * Each damage consumes a distinct insured item: two sword damages need two
194	 * insured swords, otherwise the whole claim is rejected.
195	 */
196	const matchDamagesToInsuredItems = (policy: Policy, damages: Damage[]): MatchedDamage[] => {
197	  const unclaimed = [...policy.items];
198	  return damages.map((damage) => {
199	    const index = unclaimed.findIndex((insured) => insured.type === damage.itemType);
200	    if (index === -1) throw new Error(`Item not insured: ${damage.itemType}`);
201	    return { damage, item: unclaimed.splice(index, 1)[0] };
202	  });
203	};
204	
205	/** The deductible is withheld once per damaged item, not once per incident. */
206	const reimbursementAfterDeductible = ({ damage, item }: MatchedDamage): number =>
207	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
208	
209	/**
210	 * The MHPCO does not pay out on damage that repaired the item. A single
211	 * negative entry rejects the whole claim, so this runs before any item is
212	 * matched and before the cap is drawn down — no partial settlement.
213	 */
214	const rejectNegativeDamages = (damages: Damage[]): void => {
215	  const negative = damages.find((damage) => damage.amount < 0);
216	  if (negative !== undefined) {
217	    throw new Error(`Damage amount cannot be negative: ${negative.amount}`);
218	  }
219	};
220	
221	/** Draws down the policy's remaining cap as a side effect. */
222	const settleClaim = (policy: Policy, incident: Incident): Result => {
223	  rejectNegativeDamages(incident.damages);
224	  const matched = matchDamagesToInsuredItems(policy, incident.damages);
225	  const claimedBeforeCap = sumBy(matched, reimbursementAfterDeductible);
226	  const payout = roundPayout(Math.min(claimedBeforeCap, policy.remainingCap));
227	  policy.remainingCap -= payout;
228	  return { payout, remainingCap: policy.remainingCap };
229	};
230	
231	export const runScenario = (scenario: Scenario): { results: Result[] } => {
232	  const policies = new Map<number, Policy>();
233	  let quotesSoFar = 0;
234	
235	  const results = scenario.steps.map((step, stepIndex) => {
236	    if (step.op === "quote") {
237	      const premium = quotePremium(step.items, scenario.customer, quotesSoFar > 0);
238	      quotesSoFar += 1;
239	      policies.set(stepIndex, openPolicy(step.items));
240	      return { premium };
241	    }
242	    const policy = policies.get(step.policy);
243	    if (policy === undefined) throw new Error(`No policy at step ${step.policy}`);
244	    return settleClaim(policy, step.incident);
245	  });
246	
247	  return { results };
248	};
